gOP(){return"\u0935\u0947 \u0938\u093e\u0907\u0928 \u0907\u0928 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0907\u0938\u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902\u0917\u0947 \u2014 \u0907\u0938\u0915\u0947 \u092c\u093f\u0928\u093e \u0909\u0928\u094d\u0939\u0947\u0902 \u092c\u0928\u093e\u092f\u093e \u0928\u0939\u0940\u0902 \u091c\u093e \u0938\u0915\u0924\u093e\u0964"},
gOK(){return"\u092d\u0942\u092e\u093f\u0915\u093e"},
gOO(){return"\u092c\u093f\u0915\u094d\u0930\u0940 \u091f\u0940\u092e"},
gS6(){return"\u0916\u093e\u0924\u093e \u0932\u0947\u092c\u0932"},
gHq(){return"\u092c\u0948\u0902\u0915 \u0915\u093e \u0928\u093e\u092e (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)"},
gHo(){return"\u0916\u093e\u0924\u093e \u0938\u0902\u0916\u094d\u092f\u093e (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)"},
gHs(){return"IBAN (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)"},
gS7(){return'\u0916\u093e\u0924\u093e \u0932\u0947\u092c\u0932 (\u091c\u0948\u0938\u0947 "ADCB Current")'},
gSi(){return"\u092a\u094d\u0930\u093e\u0930\u0902\u092d\u093f\u0915 \u0936\u0947\u0937"},
ga1f(){return'\u091c\u0948\u0938\u0947 "\u092b\u094d\u0930\u0902\u091f \u0921\u0947\u0938\u094d\u0915 \u092b\u094d\u0932\u094b\u091f"'},
ga1c(){return"\u0905\u092d\u093f\u0930\u0915\u094d\u0937\u0915 (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)"},
